const update = $input.first().json;
const isCallback = !!(update && update.callback_query);
return [{ json: { isCallback } }];

const msg = $('Telegram Trigger').first().json.message || {};
const chatId = String(msg.chat ? msg.chat.id : '');
const text = msg.text || (msg.photo ? '[FOTO RECEBIDA]' : (msg.voice ? '[ÁUDIO RECEBIDO]' : '[MÍDIA RECEBIDA]'));
return [{ json: { chat_id: chatId, msg_text: text, msg_ts: Date.now() } }];

const state = $('Get Buffer State').first().json;
const msgTs = $('Debounce Start').first().json.msg_ts;
const chatId = $('Debounce Start').first().json.chat_id;
const lastTs = state && state.last_msg_at ? new Date(state.last_msg_at).getTime() : msgTs;
const isLast = lastTs <= msgTs;
const combined = (state && state.pending ? state.pending : '').trim();
return [{ json: { is_last: isLast, combined_text: combined, chat_id: chatId } }];

const cq = $('Telegram Trigger').first().json.callback_query;
const data = (cq.data || '').split(':');
const type = data[0];
const action = data[1] || null;
const leadId = data[2] || null;
const messageId = cq.message ? cq.message.message_id : null;
const chatId = cq.message ? cq.message.chat.id : null;
const callbackId = cq.id;

let query = null;
let answerText = '';
let editText = '';

if (type === 'handoff') {
  if (action === 'confirm') {
    query = 'UPDATE public.leads SET pipeline_status = \'fechado\' WHERE id = \'' + leadId + '\'::uuid RETURNING id, pipeline_status;';
    answerText = '\u2705 Handoff aceito! Lead movido para fechado.';
    editText = '<b>\u2705 Handoff aceito</b>';
  } else if (action === 'cancel') {
    query = 'UPDATE public.leads SET pipeline_status = \'perdido\' WHERE id = \'' + leadId + '\'::uuid RETURNING id, pipeline_status;';
    answerText = '\u274C Handoff recusado. Lead movido para perdido.';
    editText = '<b>\u274C Handoff recusado</b>';
  }
} else if (type === 'deposit') {
  if (action === 'confirm') {
    query = 'UPDATE public.leads SET deposit_status = \'confirmado\' WHERE id = \'' + leadId + '\'::uuid RETURNING id, pipeline_status;';
    answerText = '\u2705 Sinal confirmado! Prossiga com o agendamento.';
    editText = '<b>\u2705 Sinal Recebido \u2014 Pronto para agendamento</b>';
  } else if (action === 'cancel') {
    query = 'UPDATE public.leads SET pipeline_status = \'perdido\' WHERE id = \'' + leadId + '\'::uuid RETURNING id, pipeline_status;';
    answerText = '\u274C Sinal n\u00E3o recebido. Lead movido para perdido.';
    editText = '<b>\u274C Sinal N\u00E3o Recebido</b>';
  }
}

return [{ json: {
  type,
  action,
  lead_id: leadId,
  answer_text: answerText,
  edit_text: editText,
  callback_id: callbackId,
  message_id: messageId,
  chat_id: chatId,
  query,
} }];

const currentPipeline = $('Upsert Lead').first().json.pipeline_status || 'novo';
const userMsg = $('Debounce Resolve').first().json.combined_text || '';
const agentOutput = $('AI Agent').first().json.output || '';

const sysPrompt = `Você classifica conversas de um estúdio de tatuagem. Dada a mensagem do lead e a resposta da assistente Beatriz, determine o que aconteceu e extraia os dados.

## Transições de pipeline

Pipeline atual: ${currentPipeline}

- Se Beatriz apresentou preço → pipeline=orcamento_enviado, event=quote_sent
- Se Beatriz pediu PIX/sinal/depósito → pipeline=aguardando_deposito, event=deposit_requested, extraia o valor do sinal em centavos
- Se Beatriz confirmou agendamento ("Fechado! [data] às [hora]") → pipeline=agendado, event=slot_booked, extraia a data YYYY-MM-DD e o horário HH:MM
- Se Beatriz EXPLICITAMENTE disse que vai passar o lead para o artista (ex: "vou te passar pro Bruno", "deixa eu te passar pro artista", ou disse que não há horário disponível e vai passar para o artista) → pipeline=aguardando_artista, event=handoff_triggered, extraia o motivo
- Se Beatriz usou a mensagem de corte exata — "Infelizmente não posso continuar essa conversa. Se precisar de algo, estamos à disposição." — → pipeline=bloqueado, event=lead_blocked
- NUNCA classifique como bloqueado por tom grosseiro, reclamação, xingamento ou negociação difícil — isso NÃO é bloqueio. Sem a mensagem de corte exata, nunca mude o pipeline para bloqueado.
- Se dados de qualificação foram extraídos (local, tamanho, estilo, primeira tatuagem) e pipeline=novo → pipeline=qualificando
- Se nada relevante aconteceu → pipeline=pipeline atual, event=null

## Campos de qualificação (extraia SOMENTE da mensagem do lead — NUNCA da resposta da Beatriz)

- placement: braco_externo, braco_interno, antebraco, panturrilha, tornozelo, pescoco, costela, costas, barriga, ombro, pulso, braco, peito, perna, coxa, dedo, mao, pe
- body_zone: pequeno, medio, grande, fechamento
  - fechamento: "o [local] inteiro", "fechamento", "fechar o [local]", "completo", "cobrir tudo", "o [local] todo"
  - grande: "quase tudo", "a maior parte", "grande"
  - medio: "uma área média", "metade", "médio"
  - pequeno: "só uma partinha", "um pedacinho", "só um detalhe", "pequeno"
- style: realismo, old_school, neo_tradicional, fine_line, new_school, blackwork, tradicional, geometrico, pontilhismo, aquarela, japones, oriental, tribal, floral
- first_tattoo: true se for primeira, false se já tiver outras, null se não mencionado
- significado: texto livre se mencionado
- tipo_tatuagem: "nova" se o lead disse "tatuagem nova"/"fazer uma nova"/"nova tattoo"; "cobertura" se o lead disse "cobrir"/"cobertura"/"cover-up"/"tatuagem por cima"; "reforma" se o lead disse "reformar"/"retocar"/"retoque"; null se o lead não mencionou

⚠ **FALSO POSITIVO PROIBIDO:** A pergunta da Beatriz "uma tatuagem nova, uma cobertura (cover-up) ou uma reforma" NÃO é resposta do lead. Se "cobertura"/"reforma"/"cover-up" só aparecem na fala da Beatriz (a pergunta dela), isso NÃO define o tipo_tatuagem. Extraia o tipo APENAS do que o LEAD disse. Exemplo: lead diz "quero fazer uma tatuagem nova" e Beatriz pergunta "nova, cobertura ou reforma?" → tipo_tatuagem = "nova", NUNCA "cobertura" nem "reforma".

## Campos de preço (extraia da resposta da Beatriz)

Valores SEMPRE em centavos. R$600 = 60000. R$180 = 18000.
- table_cents: preço de tabela (à vista) em centavos
- nego_cents: preço negociado final em centavos (se não houve negociação, mesmo valor da tabela)

## Motivos de handoff

cover_up, reforma, lead_requested_artist, below_piso, vague, audio_2x, no_availability

⚠ cover_up e reforma SÓ quando o LEAD explicitamente pediu cobertura/reforma ("quero cobrir", "reformar", "retocar"). As palavras "cobertura"/"reforma" na pergunta da Beatriz NÃO disparam handoff.

## REGRA CRÍTICA

NÃO classifique como handoff a menos que Beatriz tenha EXPLICITAMENTE dito que vai passar o lead para o artista. Uma resposta normal de conversa NUNCA é handoff. Se não houver frase explícita de handoff na resposta da Beatriz, use pipeline=pipeline atual e event=null.

## OUTPUT

Retorne APENAS este JSON. Use null para campos ausentes:

{
  "pipeline": "string",
  "event": "string or null",
  "qualification": {
    "placement": "string or null",
    "body_zone": "string or null",
    "style": "string or null",
    "first_tattoo": true or null,
    "significado": "string or null",
    "tipo_tatuagem": "nova | cobertura | reforma or null"
  },
  "pricing": {
    "table_cents": 60000 or null,
    "nego_cents": 60000 or null
  },
  "deposit": {
    "amount_cents": 18000 or null
  },
  "handoff": {
    "reason": "string or null"
  },
  "booking": {
    "date": "2026-08-15 or null",
    "time": "14:00 or null"
  },
  "name": "João Silva or null",
  "blocked": false
}
`;

return [{ json: {
  body: {
    model: 'openai/gpt-4o-mini',
    temperature: 0,
    messages: [
      { role: 'system', content: sysPrompt },
      { role: 'user', content: 'Lead: ' + userMsg + '\n\nBeatriz: ' + agentOutput }
    ]
  }
} }];

const resp = $input.first().json;
const content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '{}';
let parsed;
try { parsed = JSON.parse(content); } catch(e) { parsed = {}; }

const q = parsed.qualification || {};
const p = parsed.pricing || {};
const d = parsed.deposit || {};
const h = parsed.handoff || {};
const b = parsed.booking || {};
const lead = $('Upsert Lead').first().json;
const agentOutput = $('AI Agent').first().json.output || '';

// ── Deterministic tipo_tatuagem guard ──
// The LLM classifier can misread Beatriz's own question "uma tatuagem nova,
// uma cobertura (cover-up) ou uma reforma" as the lead's answer. Extract tipo
// deterministically from the LEAD's raw message so "nova" is never mislabeled.
const rawLead = ($('Debounce Resolve').first().json.combined_text || '').toLowerCase();
function detectTipo(text) {
  if (/cobertura|cobrir|cover[- ]?up|tatuagem por cima|por cima de(?:sta| uma)/.test(text)) return 'cobertura';
  if (/reforma|reformar|retocar|retoque|refazer|redesign|remodelar/.test(text)) return 'reforma';
  if (/tatuagem nova|nova tattoo|tattoo nova|fazer uma nova|uma nova tatuagem/.test(text)) return 'nova';
  return null;
}
const tipoDeterministic = detectTipo(rawLead);

// ── Transition guard — prevent invalid/repeated transitions ──
const current = lead.pipeline_status || 'novo';
let proposed = parsed.pipeline || current;

// Bloqueio: só pode virar 'bloqueado' se Beatriz REALMENTE usou a mensagem de corte
// e o lead não está em estado que nunca bloqueia (agendado/fechado/perdido).
// Nunca inferir bloqueio de um tom grosseiro ou de classificação ambígua.
const saidCutoff = /não posso continuar essa conversa/.test(agentOutput.toLowerCase());
const neverBlock = ['agendado', 'fechado', 'perdido'];
if (proposed === 'bloqueado' && (!saidCutoff || neverBlock.includes(current))) {
  proposed = current;
  parsed.event = null;
}

// Terminal states never change
const terminal = ['fechado', 'perdido', 'bloqueado'];
const validFrom = {
  'novo': ['novo', 'qualificando', 'orcamento_enviado', 'aguardando_deposito', 'agendado', 'aguardando_artista', 'bloqueado'],
  'qualificando': ['qualificando', 'orcamento_enviado', 'aguardando_deposito', 'agendado', 'aguardando_artista', 'bloqueado'],
  'orcamento_enviado': ['orcamento_enviado', 'aguardando_deposito', 'agendado', 'aguardando_artista', 'bloqueado'],
  'aguardando_deposito': ['aguardando_deposito', 'agendado', 'aguardando_artista', 'bloqueado'],
  'agendado': ['agendado'],
  'aguardando_artista': ['aguardando_artista'],
  'fechado': ['fechado'],
  'perdido': ['perdido'],
  'bloqueado': ['bloqueado'],
};

let finalPipeline = current;
let finalEvent = parsed.event || null;

if (terminal.includes(current)) {
  // Terminal — no changes, no events
  finalPipeline = current;
  finalEvent = null;
} else if (validFrom[current] && validFrom[current].includes(proposed)) {
  finalPipeline = proposed;
  // If no actual transition, suppress event (prevents repeated notifications)
  if (proposed === current) finalEvent = null;
} else {
  // Invalid transition — keep current, suppress event
  finalPipeline = current;
  finalEvent = null;
}

// ── Cover-up/reforma false-positive guard ──
// If the lead clearly said "nova" in this message, never allow a
// cover_up/reforma handoff (e.g. the classifier misread Beatriz's own
// "cobertura (cover-up) ou reforma" question as the lead's answer).
let finalHandoff = h.reason || null;
if (tipoDeterministic === 'nova' && (finalHandoff === 'cover_up' || finalHandoff === 'reforma')) {
  finalHandoff = null;
  if (finalPipeline === 'aguardando_artista') {
    finalPipeline = current;
    finalEvent = null;
  }
}

return [{ json: {
  lead_id: lead.id,
  pipeline_status: finalPipeline,
  event_type: finalEvent,
  price_updated: !!(p.table_cents),

  placement_val: q.placement || null,
  body_zone_val: q.body_zone || null,
  style_val: q.style || null,
  primeira_tatuagem_val: q.first_tattoo || null,
  significado_val: q.significado || null,
  tipo_tatuagem_val: tipoDeterministic || q.tipo_tatuagem || null,

  table_price_cents: p.table_cents || null,
  negotiated_price_cents: p.nego_cents || null,

  deposit_status_val: d.amount_cents ? 'aguardando_confirmacao' : null,
  deposit_amount_cents: d.amount_cents || null,
  booked_date_val: b.date ? (b.date + 'T' + (b.time || '12:00') + ':00') : null,
  session_duration_min_val: null,
  buffer_min_val: null,

  handoff_reason: finalHandoff,

  nome_val: parsed.name || null,
} }];

const f = $input.first().json;

function esc(s) { return String(s || '').replace(/'/g, "''"); }

const sets = [];

const ps = esc(f.pipeline_status);
sets.push(`pipeline_status = CASE
    WHEN '${ps}' = 'qualificando' AND pipeline_status = 'novo' THEN 'qualificando'::text
    WHEN '${ps}' = 'orcamento_enviado' AND pipeline_status IN ('novo','qualificando') THEN 'orcamento_enviado'::text
    WHEN '${ps}' = 'aguardando_deposito' AND pipeline_status IN ('novo','qualificando','orcamento_enviado') THEN 'aguardando_deposito'::text
    WHEN '${ps}' = 'agendado' AND pipeline_status IN ('novo','qualificando','orcamento_enviado','aguardando_deposito') THEN 'agendado'::text
    WHEN '${ps}' = 'aguardando_artista' AND pipeline_status NOT IN ('fechado','perdido','agendado') THEN 'aguardando_artista'::text
    WHEN '${ps}' = 'bloqueado' AND pipeline_status NOT IN ('fechado','perdido') THEN 'bloqueado'::text
    ELSE pipeline_status END`);

if (f.placement_val && f.placement_val !== 'null') sets.push(`placement = '${esc(f.placement_val)}'`);
if (f.body_zone_val && f.body_zone_val !== 'null') sets.push(`body_zone = '${esc(f.body_zone_val)}'`);
if (f.style_val && f.style_val !== 'null') sets.push(`style = '${esc(f.style_val)}'`);
if (f.significado_val && f.significado_val !== 'null') sets.push(`significado = '${esc(f.significado_val)}'`);
if (f.tipo_tatuagem_val && f.tipo_tatuagem_val !== 'null') sets.push(`tipo_tatuagem = '${esc(f.tipo_tatuagem_val)}'`);
if (f.deposit_status_val && f.deposit_status_val !== 'null') sets.push(`deposit_status = '${esc(f.deposit_status_val)}'`);

if (f.nome_val && f.nome_val !== 'null') sets.push(`nome = '${esc(f.nome_val)}'`);

if (f.table_price_cents !== null && f.table_price_cents !== undefined && f.table_price_cents !== 'null')
  sets.push(`table_price = ${f.table_price_cents}`);
if (f.negotiated_price_cents !== null && f.negotiated_price_cents !== undefined && f.negotiated_price_cents !== 'null')
  sets.push(`negotiated_price = ${f.negotiated_price_cents}`);
if (f.deposit_amount_cents !== null && f.deposit_amount_cents !== undefined && f.deposit_amount_cents !== 'null')
  sets.push(`deposit_amount = ${f.deposit_amount_cents}`);
if (f.session_duration_min_val !== null && f.session_duration_min_val !== undefined && f.session_duration_min_val !== 'null')
  sets.push(`session_duration_min = ${f.session_duration_min_val}`);
if (f.buffer_min_val !== null && f.buffer_min_val !== undefined && f.buffer_min_val !== 'null')
  sets.push(`buffer_min = ${f.buffer_min_val}`);

if (f.primeira_tatuagem_val === true) sets.push(`primeira_tatuagem = true`);
else if (f.primeira_tatuagem_val === false) sets.push(`primeira_tatuagem = false`);

if (f.booked_date_val && f.booked_date_val !== 'null')
  sets.push(`booked_date = '${esc(f.booked_date_val)}'::timestamptz`);

sets.push(`last_message_at = NOW()`);
sets.push(`updated_at = NOW()`);

const query = `UPDATE public.leads SET ${sets.join(', ')} WHERE id = '${esc(String(f.lead_id))}'::uuid AND artist_id = 'b0000000-0000-0000-0000-000000000001' RETURNING id, pipeline_status, deposit_status;`;

return { json: { ...f, query } };

